package com.bbmurloc.victoriaeconomics.server.storage.sqlite;

import java.util.List;

/** v8 parent company-period decisions and purpose-only household budgets. */
final class EconomyPaymentSchema {
    private EconomyPaymentSchema() {}
    static final List<String> DDL=List.of(
            "CREATE TABLE payroll_payment_runtime(id INTEGER PRIMARY KEY CHECK(id=1), processed_period INTEGER NOT NULL CHECK(typeof(processed_period)='integer' AND processed_period>=0), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0))",
            "CREATE TABLE payroll_payment_cycles(period_id INTEGER PRIMARY KEY CHECK(typeof(period_id)='integer' AND period_id>0), boundary_tick INTEGER NOT NULL CHECK(typeof(boundary_tick)='integer' AND boundary_tick>0 AND boundary_tick%1200=0 AND boundary_tick/1200=period_id), status TEXT NOT NULL CHECK(status IN ('PLANNED','ACKNOWLEDGED')), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0))",
            "CREATE TABLE payroll_payment_runs(id TEXT PRIMARY KEY NOT NULL, company_id TEXT NOT NULL REFERENCES companies(id), period_id INTEGER NOT NULL REFERENCES payroll_payment_cycles(period_id), status TEXT NOT NULL CHECK(status IN ('PENDING','BLOCKED','COMPLETED')), decided_tick INTEGER CHECK(decided_tick IS NULL OR (typeof(decided_tick)='integer' AND decided_tick>=0)), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0), UNIQUE(company_id,period_id), CHECK((status IN ('PENDING','BLOCKED') AND decided_tick IS NULL AND revision=0) OR (status='COMPLETED' AND decided_tick IS NOT NULL AND revision=1)))",
            "CREATE TABLE payroll_payment_partitions(run_id TEXT NOT NULL REFERENCES payroll_payment_runs(id), currency_id TEXT NOT NULL REFERENCES currencies(id), source_account TEXT NOT NULL REFERENCES finance_accounts(id), cash_balance INTEGER NOT NULL CHECK(typeof(cash_balance)='integer' AND cash_balance>=0), reserved_cash INTEGER NOT NULL CHECK(typeof(reserved_cash)='integer' AND reserved_cash>=0 AND reserved_cash<=cash_balance), ledger_sequence INTEGER NOT NULL REFERENCES finance_ledger(sequence), total_due INTEGER NOT NULL CHECK(typeof(total_due)='integer' AND total_due>0), paid INTEGER NOT NULL CHECK(typeof(paid)='integer' AND paid>=0 AND paid<=cash_balance-reserved_cash AND paid<=total_due), PRIMARY KEY(run_id,currency_id))",
            "CREATE TABLE payroll_payment_cash_locks(run_id TEXT NOT NULL, currency_id TEXT NOT NULL, reservation_id TEXT NOT NULL REFERENCES cash_reservations(id), PRIMARY KEY(run_id,currency_id,reservation_id), FOREIGN KEY(run_id,currency_id) REFERENCES payroll_payment_partitions(run_id,currency_id))",
            "CREATE TABLE payroll_payment_lines(run_id TEXT NOT NULL REFERENCES payroll_payment_runs(id), line INTEGER NOT NULL CHECK(typeof(line)='integer' AND line>=0), segment_id TEXT NOT NULL, liability_period INTEGER NOT NULL, building_id TEXT NOT NULL REFERENCES economic_buildings(id), region_id TEXT NOT NULL REFERENCES regions(id), currency_id TEXT NOT NULL REFERENCES currencies(id), recipient_account TEXT NOT NULL REFERENCES finance_accounts(id), debt_before INTEGER NOT NULL CHECK(typeof(debt_before)='integer' AND debt_before>0), amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>=0 AND amount<=debt_before), transfer_event TEXT UNIQUE REFERENCES finance_events(id), PRIMARY KEY(run_id,line), UNIQUE(run_id,segment_id,liability_period), FOREIGN KEY(segment_id,liability_period) REFERENCES payroll_liabilities(segment_id,period_id), FOREIGN KEY(run_id,currency_id) REFERENCES payroll_payment_partitions(run_id,currency_id), CHECK((amount=0 AND transfer_event IS NULL) OR (amount>0 AND transfer_event IS NOT NULL)))",
            "CREATE TABLE payroll_payment_failures(run_id TEXT NOT NULL REFERENCES payroll_payment_runs(id), attempt INTEGER NOT NULL CHECK(typeof(attempt)='integer' AND attempt>0), observed_tick INTEGER NOT NULL CHECK(typeof(observed_tick)='integer' AND observed_tick>=0), reason TEXT NOT NULL CHECK(length(trim(reason))>0), PRIMARY KEY(run_id,attempt))",
            "CREATE TABLE regional_household_sectors(region_id TEXT NOT NULL REFERENCES regions(id), currency_id TEXT NOT NULL REFERENCES currencies(id), account_id TEXT NOT NULL UNIQUE REFERENCES finance_accounts(id), PRIMARY KEY(region_id,currency_id))",
            "CREATE TABLE regional_household_budgets(region_id TEXT NOT NULL, currency_id TEXT NOT NULL, consumption INTEGER NOT NULL CHECK(typeof(consumption)='integer' AND consumption>=0), savings INTEGER NOT NULL CHECK(typeof(savings)='integer' AND savings>=0), carried_period INTEGER NOT NULL CHECK(typeof(carried_period)='integer' AND carried_period>=0), revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=0), PRIMARY KEY(region_id,currency_id), FOREIGN KEY(region_id,currency_id) REFERENCES regional_household_sectors(region_id,currency_id))");
}
